/** Attribute keys the runtime owns on spans. Author tags cannot set them. */
export const RESERVED_SPAN_ATTRIBUTES = new Set([
    "cursor.conversation.id",
    "agent_sdk.session_id",
    "agent_sdk.agent",
    "agent_sdk.turn_id",
    "agent_sdk.framework",
]);
/**
 * Keys the runtime writes on session metrics. `setMetricAttributes`
 * rejects these. A caller value would replace the runtime value.
 */
export const RESERVED_METRIC_ATTRIBUTES = new Set([
    ...RESERVED_SPAN_ATTRIBUTES,
    "agent_sdk.channel",
    "agent_sdk.sdk_agent_id",
    "agent_sdk.sdk_agent_url",
    "agent_sdk.subagent_name",
    "agent_sdk.turn_status",
    "cursor.token.type",
    "cursor.tool.kind",
    "cursor.tool.name",
    "cursor.tool.status",
]);
